(async()=>{try{await ProximaPersistence.ready;for(const name of ['schedule-fixture','remote-domain','store','schedule-zoom','life-clock','date-strip','marquee-controller','exact-timeline','app']){await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=name+'.js?v=calendar-native-peek-v173';script.onload=resolve;script.onerror=reject;document.body.append(script);});if(name==='store'){globalThis.__papersSharedData=source=>Store.remoteProjection(source);globalThis.__papersFlushBeforeClose=()=>Store.flushCommands();}if(name==='store'&&!localStorage.getItem('proxima.timeline.rows-migrated.v1')){const result=await Store.command({type:'timeline.migrate'});if(!result.ok)throw new Error('Could not migrate timeline rows');localStorage.setItem('proxima.timeline.rows-migrated.v1','1');}}await import('./remote-devices.js');}catch(error){const message=document.createElement('p');message.setAttribute('role','alert');message.textContent='Could not open saved data. Your existing data is preserved. '+error.message;document.body.prepend(message);console.error(error);}})();
